CREATE SCHEMA App
GO
CREATE TABLE App.Item (Id int NOT NULL CONSTRAINT PK_Item PRIMARY KEY, Name nvarchar(50) NOT NULL, Price money NULL CONSTRAINT DF_Item_Price DEFAULT (0))
GO
CREATE INDEX IX_Item_Name ON App.Item (Name)
GO
CREATE VIEW App.Cheap AS SELECT Id, Name FROM App.Item WHERE Price < 10
GO
CREATE PROCEDURE App.GetItem @Id int AS SELECT * FROM App.Item WHERE Id = @Id
GO
CREATE FUNCTION App.Twice (@x int) RETURNS int AS BEGIN RETURN 2 * @x END
GO
CREATE SEQUENCE App.Seq START WITH 1
GO
CREATE SYNONYM App.ItemSyn FOR App.Item
GO
CREATE ROLE AppReaders
GO
GRANT SELECT ON SCHEMA::App TO AppReaders
